import '../../domain/domain.dart';
import '../json.dart';
import 'food_item_mapper.dart';

/// Builds a draft from an estimate returned by the API. [id] is generated by
/// the caller because estimates do not carry one.
MealDraft mealDraftFromEstimate(
  Json json, {
  required String id,
  required MealSource source,
  String? imagePath,
}) => MealDraft(
  id: id,
  source: source,
  imagePath: imagePath,
  items: jsonRows(json['items']).map(foodItemFromJson).toList(),
  confidence: Confidence.values.byName(json['confidence'] as String? ?? 'low'),
  assumptions: (json['assumptions'] as List? ?? [])
      .whereType<String>()
      .where((value) => value.isNotEmpty)
      .toList(),
  model: json['model'] as String?,
  question: json['question'] as String?,
  edited: json['user_edited'] as bool? ?? false,
);

Json mealDraftToJson(MealDraft draft) => {
  'id': draft.id,
  'source': draft.source.name,
  'items': draft.items.map(foodItemToJson).toList(),
  'confidence': draft.confidence.name,
  'assumptions': draft.assumptions,
  'image_storage_path': draft.imagePath,
  'model': draft.model,
  'user_edited': draft.edited,
  if (draft.expectedUpdatedAt != null)
    'expected_updated_at': draft.expectedUpdatedAt,
};

SavedMeal savedMealFromJson(Json json) => SavedMeal(
  mealDraftFromEstimate(
    json,
    id: json['id'] as String,
    source: MealSource.values.byName(json['source'] as String),
    imagePath: json['image_storage_path'] as String?,
  ),
  DateTime.parse(json['consumed_at'] as String),
  json['updated_at'] as String,
  json['representative_calories'] as int,
);

Json savedMealToJson(SavedMeal meal) => {
  ...mealDraftToJson(meal.draft),
  'consumed_at': meal.at.toUtc().toIso8601String(),
  'updated_at': meal.updatedAt,
  'representative_calories': meal.representative,
};
